const item = $input.first();
const payload = item?.json ?? {};
const staticData = $getWorkflowStaticData('global');

staticData.dialogStates ??= {};
staticData.seenMessages ??= {};

const now = Date.now();
const DEDUPE_TTL_MS = 7 * 24 * 60 * 60 * 1000;

for (const [key, value] of Object.entries(staticData.seenMessages)) {
  if (!value || now - value > DEDUPE_TTL_MS) {
    delete staticData.seenMessages[key];
  }
}

const eventName = String(payload.event || '').toLowerCase();
const message = payload.payload || {};

const messageId = String(
  payload.id ||
  message.id ||
  ''
);

if (messageId && staticData.seenMessages[messageId]) {
  return [];
}
if (messageId) {
  staticData.seenMessages[messageId] = now;
}

const fromMe = Boolean(message.fromMe || false);

const rawChatId = String(
  message.from ||
  message.to ||
  ''
).trim();

const phoneNumber = String(rawChatId)
  .replace(/@.+$/, '')
  .replace(/[^\d]/g, '');

const text = String(message.body || '').trim();

const hasFile = Boolean(message.hasMedia);
const media = message.media || null;

const fileName = String(
  media?.filename ||
  media?.fileName ||
  ''
).trim();

const mimeType = String(
  media?.mimetype ||
  media?.mimeType ||
  ''
).toLowerCase();

const fileLink = String(
  media?.url ||
  media?.link ||
  media?.downloadUrl ||
  ''
).trim();

const hasPdf = Boolean(
  hasFile && (
    fileName.toLowerCase().endsWith('.pdf') ||
    mimeType.includes('pdf') ||
    fileLink.toLowerCase().includes('.pdf')
  )
);

const hasAnyUsefulContent = Boolean(text || hasFile);

const ignoredEvents = [
  'message.ack',
  'session.status',
  'state.change',
  'group.join',
  'group.leave',
  'presence.update',
  'call.received',
  'call.accepted',
  'call.rejected'
];

const shouldIgnore =
  fromMe ||
  !rawChatId ||
  !hasAnyUsefulContent ||
  ignoredEvents.includes(eventName);

if (shouldIgnore) {
  return [];
}

const currentState = staticData.dialogStates[rawChatId] || {
  language: '',
  company: '',
  company_activities: '',
  company_activities_ru: '',
  catalog_link: '',
  catalog_received: false,
  status: 'await_company',
  saved_at: '',
};

function detectLanguage(firstText) {
  const normalized = String(firstText || '').trim().toLowerCase();
  if (!normalized) return '';
  if (normalized.startsWith('hi') || normalized.startsWith('hello')) return 'en';
  if (normalized.startsWith('привет') || normalized.startsWith('здравствуйте')) return 'ru';
  if (normalized.startsWith('сәлем') || normalized.startsWith('сәлеметсіз бе')) return 'kz';
  if (/[әіңғүұқөһ]/i.test(normalized)) return 'kz';
  if (/[а-яё]/i.test(normalized)) return 'ru';
  return 'en';
}

const language = currentState.language || detectLanguage(text) || 'en';

const normalizedText = text.trim().toLowerCase();

const isThanksMessage =
  /^(thanks|thank you|thx|thank u|ty|спасибо|благодарю|рахмет|ок|ok|okay|👍|🙏|😊|😁|😄|🙂|🤝)+$/i.test(normalizedText) ||
  [
    'thanks',
    'thank you',
    'thx',
    'thank u',
    'ty',
    'спасибо',
    'благодарю',
    'рахмет',
    'ок',
    'ok',
    'okay',
    '👍',
    '🙏',
    '😊',
    '😁',
    '😄',
    '🙂',
    '🤝'
  ].includes(normalizedText);

const isResetCommand =
  normalizedText === '/reset' ||
  normalizedText === 'reset';

const messageDate = new Date().toISOString().slice(0, 10);

return [{
  json: {
    event_name: eventName,
    message_id: messageId,
    chat_id: rawChatId,
    phone_number: phoneNumber,
    text,
    file_link_candidate: fileLink,
    file_name: fileName,
    mime_type: mimeType,
    has_file: hasFile,
    has_pdf: hasPdf,
    language,
    message_date: messageDate,
    current_state: currentState,
    is_thanks_message: isThanksMessage,
    is_reset_command: isResetCommand,
    raw_payload: payload,
  }
}];

const raw = String($json.output ?? '').trim();

let analysis;
try {
  analysis = JSON.parse(raw);
} catch (error) {
  analysis = {
    company_candidate: '',
    company_activities_candidate: '',
    company_activities_ru: '',
    parse_error: error.message,
  };
}

const normalized = $('Normalize Event').item.json;
const staticData = $getWorkflowStaticData('global');
staticData.dialogStates ??= {};

const previousState = normalized.current_state || {};

const state = {
  language: normalized.language || previousState.language || 'en',
  company: previousState.company || '',
  company_activities: previousState.company_activities || '',
  company_activities_ru: previousState.company_activities_ru || '',
  catalog_link: previousState.catalog_link || '',
  catalog_received: previousState.catalog_received || false,
  status: previousState.status || 'await_company',
  saved_at: previousState.saved_at || '',
};

const companyCandidate = String(analysis.company_candidate || '').trim();
const activityCandidate = String(analysis.company_activities_candidate || '').trim();
const activityRuCandidate = String(analysis.company_activities_ru || '').trim();

if (!state.company && companyCandidate) {
  state.company = companyCandidate;
}

if (!state.company_activities && activityCandidate) {
  state.company_activities = activityCandidate;
  state.company_activities_ru = activityRuCandidate || activityCandidate;
}

if (!state.catalog_received && normalized.has_pdf) {
  state.catalog_received = true;
}

if (!state.catalog_link && normalized.has_pdf) {
  state.catalog_link =
    normalized.file_link_candidate ||
    normalized.file_name ||
    'telegram_pdf_received';
}

let next_action = 'ask_company';

if (state.company && !state.company_activities) {
  next_action = 'ask_activity';
  state.status = 'await_activity';
} else if (state.company && state.company_activities && !state.catalog_received) {
  next_action = 'ask_catalog';
  state.status = 'await_catalog';
} else if (state.company && state.company_activities && state.catalog_received) {
  next_action = 'complete';
  state.status = 'completed';
} else {
  state.status = 'await_company';
}

const isCompleted = state.status === 'completed';
const alreadyCompleted = previousState.status === 'completed';
const shouldSave = next_action === 'complete' && !alreadyCompleted;

state.saved_at = new Date().toISOString();
staticData.dialogStates[normalized.chat_id] = state;

return [{
  json: {
    ...normalized,
    analysis,
    updated_state: state,
    next_action,
    should_save: shouldSave,
    already_completed: alreadyCompleted,
    is_completed: isCompleted,
    company: state.company,
    company_activities: state.company_activities,
    company_activities_ru: state.company_activities_ru,
    catalog_link: state.catalog_link,
    catalog_received: state.catalog_received,
  }
}];

const staticData = $getWorkflowStaticData('global');

staticData.dialogStates ??= {};
staticData.seenMessages ??= {};

const chatId = $json.chat_id;

if (chatId && staticData.dialogStates[chatId]) {
  delete staticData.dialogStates[chatId];
}

staticData.seenMessages = {};

return [
  {
    json: {
      ...$json,
      reply_text: 'Память по этому чату очищена.'
    }
  }
];
